// tb_top.sv: clock, reset, DUT, interface, the virtual-interface handoff and
// run_test(). Complete: you do not edit this file, except to plant a bug with
// +define+ARB_BUG=1 or +define+ARB_BUG=2 on the command line (step 6).
`ifndef ARB_BUG
`define ARB_BUG 0
`endif

module tb_top;
  timeunit 1ns; timeprecision 1ps;

  import uvm_pkg::*;
  import arb_pkg::*;

  logic clk = 1'b0;
  always #5 clk = ~clk;              // rising edges at 5, 15, 25 ns ...

  arb_if #(.N(ARB_N)) bus (.clk(clk));

  rr_arbiter #(.N(ARB_N), .BUG(`ARB_BUG)) dut (
    .clk  (clk),
    .rst_n(bus.rst_n),
    .req  (bus.req),
    .gnt  (bus.gnt)
  );

  // Synchronous reset for the edges at 5, 15 and 25 ns, released just after 25 ns.
  initial begin
    bus.rst_n = 1'b0;
    repeat (3) @(posedge clk);
    bus.rst_n <= 1'b1;
  end

  initial begin
    uvm_config_db#(virtual arb_if #(ARB_N))::set(null, "uvm_test_top.env.agent.*", "vif", bus);
    run_test("arb_regress_test");    // +UVM_TESTNAME=<test> picks another
  end
endmodule
